void handle_vm_cmdExchangeOpen(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 4) return;
    uint32_t v = rd32be(body, 0);
    applyLpc("cmd_exchange_open", {make_int(cl.clientNo), make_int(v)});
}

